<template>
  <section class="release-editor" aria-label="Release workflow configuration">
    <div class="editor-tabs" role="tablist" aria-label="Workflow configuration">
      <button :class="{ active: activeTab === 'destinations' }" role="tab" :aria-selected="activeTab === 'destinations'" @click="activeTab = 'destinations'"><i class="mdi mdi-upload-multiple" /> Destinations <span>{{ modelValue.destinations.length }}</span></button>
      <button :class="{ active: activeTab === 'packagers' }" role="tab" :aria-selected="activeTab === 'packagers'" @click="activeTab = 'packagers'"><i class="mdi mdi-package-variant-closed" /> Packagers <span>{{ modelValue.packagers.length }}</span></button>
    </div>

    <div v-if="activeTab === 'destinations'" class="tab-panel" role="tabpanel">
      <div class="panel-toolbar"><div><h2>Destinations</h2><p>Each attached slot delivers one exact artifact.</p></div><Select v-model="destinationToAdd" :options="availableServices" optionLabel="label" optionValue="id" placeholder="Add destination" class="add-select" @change="addDestination" /></div>
      <div v-if="!modelValue.destinations.length" class="empty-state">Add a destination to create its native delivery slots.</div>
      <article v-for="destination in modelValue.destinations" :key="destination.id" class="entity-card destination-card" :class="{ inactive: !destination.enabled }">
        <div class="entity-header"><div class="entity-icon"><img v-if="destination.serviceId === 'itch'" :src="itchIcon" alt="" /><img v-else-if="destination.serviceId === 'poki'" :src="pokiIcon" alt="" /><i v-else class="mdi" :class="service(destination.serviceId).icon" /></div><div class="entity-title"><strong>{{ service(destination.serviceId).label }}</strong><small>{{ destination.slots.length }} {{ service(destination.serviceId).slotLabel }}{{ destination.slots.length === 1 ? '' : 's' }} · {{ destinationSummary(destination) }}</small></div><Tag :value="destinationStatus(destination)" :severity="destinationStatus(destination) === 'Ready' ? 'success' : 'secondary'" /><ToggleSwitch v-model="destination.enabled" :inputId="`destination-enabled-${destination.id}`" :aria-label="`${service(destination.serviceId).label} enabled`" /><Button v-if="destinationFields(destination.serviceId).length" icon="mdi mdi-cog-outline" text rounded :aria-label="`Configure ${service(destination.serviceId).label}`" @click="openDestination(destination)" /><Button icon="mdi mdi-delete-outline" text rounded severity="danger" :aria-label="`Remove ${service(destination.serviceId).label}`" @click="removeDestination(destination.id)" /><Button :icon="expandedDestinationIds.has(destination.id) ? 'mdi mdi-chevron-up' : 'mdi mdi-chevron-down'" text rounded :aria-label="expandedDestinationIds.has(destination.id) ? `Collapse ${service(destination.serviceId).label}` : `Expand ${service(destination.serviceId).label}`" @click="toggleDestination(destination.id)" /></div>
        <div v-if="expandedDestinationIds.has(destination.id)">
        <div class="slots" aria-label="Delivery slots"><div v-for="slot in destination.slots" :key="slot.id" class="slot-card" :class="{ invalid: slot.enabled !== false && !slotIsConfigured(destination, slot), inactive: slot.enabled === false }"><div class="slot-heading"><span class="slot-icon" aria-hidden="true"><img v-if="destination.serviceId === 'itch'" :src="itchIcon" alt="" /><img v-else-if="destination.serviceId === 'poki'" :src="pokiIcon" alt="" /><i v-else class="mdi" :class="slotIcon(destination.serviceId)" /></span><div class="slot-title"><span class="slot-kind">{{ service(destination.serviceId).slotLabel }}</span><strong>{{ slotLabel(slot) }}</strong><small>{{ slotSummary(destination, slot) }}</small></div><ToggleSwitch :model-value="slot.enabled !== false" :inputId="`slot-enabled-${slot.id}`" :aria-label="`${service(destination.serviceId).slotLabel} ${slotLabel(slot)} enabled`" @update:modelValue="setSlotEnabled(slot, $event)" /><Button icon="mdi mdi-cog-outline" text rounded :aria-label="`Configure ${service(destination.serviceId).slotLabel}`" @click="openSlot(destination, slot)" /><Button icon="mdi mdi-delete-outline" text rounded severity="danger" :aria-label="`Remove ${service(destination.serviceId).slotLabel}`" @click="removeSlot(destination, slot.id)" /></div></div></div>
        <Button class="add-slot" text :label="`Add ${service(destination.serviceId).slotLabel}`" icon="mdi mdi-plus" :disabled="!slotOptions(destination).length" @click="addSlot(destination)" /></div>
      </article>
    </div>

    <div v-else class="tab-panel" role="tabpanel">
      <div class="panel-toolbar"><div><h2>Packagers</h2><p>Configure targets once; destinations select exact outputs.</p></div><Select v-model="packagerToAdd" :options="packagerDefinitions" optionLabel="label" optionValue="id" placeholder="Add packager" class="add-select" @change="addPackager" /></div>
      <div v-if="!modelValue.packagers.length" class="empty-state">Add a packager to create build outputs.</div>
      <article v-for="packager in modelValue.packagers" :key="packager.id" class="entity-card packager-card" :class="{ inactive: !packager.enabled }">
        <div class="entity-header"><div class="entity-icon"><i class="mdi" :class="packager.definitionId === 'web' ? 'mdi-web' : packager.definitionId === 'tauri' ? 'mdi-lightning-bolt-outline' : 'mdi-desktop-classic'" /></div><div class="entity-title"><strong>{{ packager.name }}</strong><small>{{ definition(packager.definitionId).label }} · {{ outputs(packager).length }} artifacts</small></div><ToggleSwitch v-model="packager.enabled" :inputId="`packager-enabled-${packager.id}`" :aria-label="`${packager.name} enabled`" /><Button icon="mdi mdi-content-copy" text rounded :aria-label="`Duplicate ${packager.name}`" @click="duplicatePackager(packager)" /><Button icon="mdi mdi-cog-outline" text rounded :aria-label="`Configure ${packager.name}`" @click="openPackager(packager)" /><Button icon="mdi mdi-delete-outline" text rounded severity="danger" :disabled="consumers(packager.id).length > 0" :aria-label="`Delete ${packager.name}`" v-tooltip.bottom="consumers(packager.id).length ? `Used by ${consumers(packager.id).join(', ')}` : `Delete ${packager.name}`" @click="removePackager(packager.id)" /></div>
        <div class="packager-summary"><span v-for="target in outputs(packager)" :key="target.id" class="summary-chip"><i class="mdi mdi-package-variant-closed" /> {{ target.label }}</span><span v-for="feature in definition(packager.definitionId).features" :key="feature" class="feature"><i class="mdi mdi-check-circle-outline" /> {{ feature }}</span><span v-if="!outputs(packager).length" class="unavailable">No targets selected</span></div>
        <div class="target-list"><div v-for="target in definition(packager.definitionId).outputs" :key="target.id" class="target-row" :class="{ unavailable: !availability(packager, target.id).available }" v-tooltip.bottom="targetLockReason(packager, target.id)"><i class="mdi" :class="selectedTarget(packager, target.id) ? 'mdi-check-circle-outline' : 'mdi-circle-outline'" /><span><strong>{{ target.label }}</strong><small>{{ target.platform }} · {{ target.format }} · {{ target.architecture }}</small></span><em v-if="!availability(packager, target.id).available"><i class="mdi mdi-lock-outline" /> {{ availability(packager, target.id).reason }}</em></div></div>
        <div v-if="consumers(packager.id).length" class="consumer-note"><i class="mdi mdi-link-variant" /> Used by {{ consumers(packager.id).join(', ') }}</div>
      </article>
    </div>

    <Dialog v-model:visible="packagerDialogVisible" modal :header="packagerDialog ? `Configure ${packagerDialog.name}` : 'Configure packager'" :style="{ width: '760px', maxWidth: '94vw' }"><div v-if="packagerDialog" class="dialog-form"><div class="option-grid"><label class="option-field option-name">Packager name<InputText v-model="packagerDialog.name" @update:modelValue="touch" /></label><div v-for="field in definition(packagerDialog.definitionId).fields" :key="field.key" class="option-field"><label :for="`dialog-option-${packagerDialog.id}-${field.key}`">{{ field.label }}</label><small v-if="field.description" class="field-help">{{ field.description }}</small><ToggleSwitch v-if="field.kind === 'boolean'" :inputId="`dialog-option-${packagerDialog.id}-${field.key}`" :model-value="fieldValue(packagerDialog, field) as boolean" @update:modelValue="setField(packagerDialog, field, $event)" /><InputNumber v-else-if="field.kind === 'number'" :inputId="`dialog-option-${packagerDialog.id}-${field.key}`" :model-value="fieldValue(packagerDialog, field) as number" :useGrouping="false" :placeholder="field.placeholder" @update:modelValue="setField(packagerDialog, field, $event)" /><InputText v-else :id="`dialog-option-${packagerDialog.id}-${field.key}`" :model-value="fieldValue(packagerDialog, field) as string" :placeholder="field.placeholder" @update:modelValue="setField(packagerDialog, field, $event)" /></div></div><div class="dialog-section"><h3>Targets</h3><p class="dialog-copy">Targets remain visible across hosts. Unsupported targets are faded and explain why they cannot run here.</p><div class="dialog-targets"><label v-for="target in definition(packagerDialog.definitionId).outputs" :key="target.id" class="target-row" :class="{ unavailable: !availability(packagerDialog, target.id).available }" v-tooltip.bottom="targetLockReason(packagerDialog, target.id)"><Checkbox :modelValue="selectedTarget(packagerDialog, target.id)" binary :inputId="`dialog-target-${packagerDialog.id}-${target.id}`" :disabled="targetDisabled(packagerDialog, target.id)" @update:modelValue="setTarget(packagerDialog, target.id, $event)" /><span><strong>{{ target.label }}</strong><small>{{ target.platform }} · {{ target.format }} · {{ target.architecture }}</small></span><em v-if="!availability(packagerDialog, target.id).available"><i class="mdi mdi-lock-outline" /> {{ availability(packagerDialog, target.id).reason }}</em></label></div></div></div><template #footer><Button label="Done" @click="packagerDialog = undefined" /></template></Dialog>
    <Dialog v-model:visible="destinationDialogVisible" modal :header="destinationDialog ? `Configure ${service(destinationDialog.serviceId).label}` : 'Configure destination'" :style="{ width: '520px', maxWidth: '94vw' }"><div v-if="destinationDialog" class="dialog-form"><div class="option-grid destination-dialog-fields"><div v-for="field in destinationFields(destinationDialog.serviceId)" :key="field.key" class="option-field"><label :for="`destination-option-${destinationDialog.id}-${field.key}`">{{ field.label }}</label><small v-if="field.description" class="field-help">{{ field.description }}</small><div v-if="field.key === 'accountConnectionId'" class="connection-picker"><Select :id="`destination-option-${destinationDialog.id}-${field.key}`" :model-value="String(destinationDialog.config[field.key] || '')" :options="connectionOptions(destinationDialog.serviceId)" optionLabel="name" optionValue="id" filter showClear :placeholder="field.placeholder" emptyMessage="No saved connection found" @update:modelValue="setDestinationField(destinationDialog, field.key, $event)" /><Button label="Add connection" text size="small" @click="emit('add-connection', destinationDialog.serviceId)" /></div><InputText v-else :id="`destination-option-${destinationDialog.id}-${field.key}`" :model-value="String(destinationDialog.config[field.key] || '')" :placeholder="field.placeholder" @update:modelValue="setDestinationField(destinationDialog, field.key, $event)" /></div></div><small v-if="!destinationInfoReady(destinationDialog)" class="unavailable"><i class="mdi mdi-alert-circle-outline" /> {{ destinationInfoReason(destinationDialog) }}</small></div><template #footer><Button label="Done" @click="destinationDialog = undefined" /></template></Dialog>
    <Dialog v-model:visible="slotDialogVisible" modal :header="slotDialog ? `Configure ${service(slotDialog.destination.serviceId).slotLabel}` : 'Configure slot'" :style="{ width: '520px', maxWidth: '94vw' }"><div v-if="slotDialog" class="dialog-form"><div class="option-grid slot-dialog-fields"><div class="option-field artifact-field"><label :for="`slot-input-${slotDialog.slot.id}`">Packager artifact</label><Select :id="`slot-input-${slotDialog.slot.id}`" :model-value="slotKey(slotDialog.slot)" :options="slotOptions(slotDialog.destination)" optionLabel="label" optionValue="key" class="slot-select" @update:modelValue="setSlotInput(slotDialog.destination, slotDialog.slot, $event)" /></div><div v-if="slotDialog.destination.serviceId === 'steam'" class="option-field"><label :for="`depot-name-${slotDialog.slot.id}`">Depot name</label><InputText :id="`depot-name-${slotDialog.slot.id}`" :model-value="String(slotDialog.slot.config.name || '')" placeholder="Windows production" @update:modelValue="setSlotConfig(slotDialog.slot, 'name', $event)" /></div><div v-if="slotDialog.destination.serviceId === 'steam'" class="option-field"><label :for="`depot-${slotDialog.slot.id}`">Depot ID</label><InputText :id="`depot-${slotDialog.slot.id}`" :model-value="String(slotDialog.slot.config.depotId || '')" placeholder="123456" @update:modelValue="setSlotConfig(slotDialog.slot, 'depotId', $event)" /></div><div v-else-if="slotDialog.destination.serviceId === 'itch'" class="option-field"><label :for="`channel-${slotDialog.slot.id}`">Channel name</label><InputText :id="`channel-${slotDialog.slot.id}`" :model-value="String(slotDialog.slot.config.channel || '')" placeholder="windows" @update:modelValue="setSlotConfig(slotDialog.slot, 'channel', $event)" /></div><div v-else-if="slotDialog.destination.serviceId === 'web-folder'" class="option-field"><label :for="`folder-${slotDialog.slot.id}`">Output folder</label><PathPicker :model-value="String(slotDialog.slot.config.outputDir || slotDialog.destination.config.outputDir || '')" label="output folder" placeholder="Choose the folder where files will be copied" @update:modelValue="setSlotConfig(slotDialog.slot, 'outputDir', $event)" /></div><div v-else-if="slotDialog.destination.serviceId === 'zip'" class="option-field"><label :for="`zip-${slotDialog.slot.id}`">ZIP file</label><PathPicker :model-value="String(slotDialog.slot.config.outputPath || '')" kind="file" label="ZIP file" placeholder="Choose where to save the ZIP" @update:modelValue="setSlotConfig(slotDialog.slot, 'outputPath', $event)" /></div></div></div><template #footer><Button label="Done" @click="slotDialog = undefined" /></template></Dialog>
  </section>
</template>

<script setup lang="ts">
import { computed, ref } from "vue";
import Button from "primevue/button";
import Checkbox from "primevue/checkbox";
import Dialog from "primevue/dialog";
import InputText from "primevue/inputtext";
import InputNumber from "primevue/inputnumber";
import Select from "primevue/select";
import Tag from "primevue/tag";
import ToggleSwitch from "primevue/toggleswitch";
import PathPicker from "@renderer/components/PathPicker.vue";
import itchIcon from "../../../../plugins/plugin-itch/src/assets/itch-icon.webp";
import pokiIcon from "../../../../plugins/plugin-poki/src/assets/poki-icon.webp";
import { PACKAGER_DEFINITIONS, SERVICE_DEFINITIONS, createDefaultDestination, createDefaultPackager, getTargetAvailability, outputDescriptor, outputsForPackager, type ArtifactOutputDescriptor, type ReleaseHostCapabilities, type WorkflowArtifactOutputId, type WorkflowConfigV2, type WorkflowDestinationV2, type WorkflowDeliverySlot, type WorkflowPackager } from "@pipelab/shared";

const props = defineProps<{ modelValue: WorkflowConfigV2; capabilities?: ReleaseHostCapabilities; connections?: Array<{ id: string; name: string; pluginName?: string; integrationName?: string }> }>();
const emit = defineEmits<{ "update:modelValue": [value: WorkflowConfigV2]; "add-connection": [serviceId: WorkflowDestinationV2["serviceId"]] }>();
const activeTab = ref<"destinations" | "packagers">("destinations");
const destinationToAdd = ref<string>();
const packagerToAdd = ref<string>();
const expandedDestinationIds = ref(new Set<string>());
const packagerDialog = ref<WorkflowPackager>();
const destinationDialog = ref<WorkflowDestinationV2>();
const slotDialog = ref<{ destination: WorkflowDestinationV2; slot: WorkflowDeliverySlot }>();
const modelValue = props.modelValue;
const packagerDefinitions = Object.values(PACKAGER_DEFINITIONS);
const availableServices = computed(() => Object.values(SERVICE_DEFINITIONS).filter((service) => !modelValue.destinations.some((destination) => destination.serviceId === service.id)));
const host = computed(() => props.capabilities?.host || { platform: "linux" as const, architecture: "x64" });
const definition = (id: WorkflowPackager["definitionId"]) => PACKAGER_DEFINITIONS[id];
const service = (id: WorkflowDestinationV2["serviceId"]) => SERVICE_DEFINITIONS[id];
const slotIcon = (id: WorkflowDestinationV2["serviceId"]) => id === "steam" ? "mdi-package-variant-closed" : id === "itch" || id === "poki" ? "mdi-transit-connection-variant" : id === "web-folder" ? "mdi-folder-upload-outline" : "mdi-folder-zip-outline";
const outputs = (packager: WorkflowPackager) => outputsForPackager(packager);
const touch = () => emit("update:modelValue", modelValue);
const addPackager = () => { if (!packagerToAdd.value) return; modelValue.packagers.push(createDefaultPackager(packagerToAdd.value as WorkflowPackager["definitionId"], undefined, props.capabilities)); packagerToAdd.value = undefined; touch(); };
const duplicatePackager = (packager: WorkflowPackager) => { modelValue.packagers.push({ ...packager, id: `${packager.id}-copy-${Math.random().toString(36).slice(2, 6)}`, name: `${packager.name} copy`, config: { ...packager.config, targets: Array.isArray(packager.config.targets) ? [...packager.config.targets] : undefined } }); touch(); };
const consumers = (id: string) => modelValue.destinations.flatMap((destination) => destination.slots.filter((slot) => slot.input.packagerId === id).map(() => `${service(destination.serviceId).label} · ${destination.slots.length} ${service(destination.serviceId).slotLabel}${destination.slots.length === 1 ? "" : "s"}`));
const removePackager = (id: string) => { if (consumers(id).length) return; modelValue.packagers = modelValue.packagers.filter((packager) => packager.id !== id); touch(); };
const packagerDialogVisible = computed({ get: () => !!packagerDialog.value, set: (visible: boolean) => { if (!visible) packagerDialog.value = undefined; } });
const destinationDialogVisible = computed({ get: () => !!destinationDialog.value, set: (visible: boolean) => { if (!visible) destinationDialog.value = undefined; } });
const slotDialogVisible = computed({ get: () => !!slotDialog.value, set: (visible: boolean) => { if (!visible) slotDialog.value = undefined; } });
const openPackager = (packager: WorkflowPackager) => { packagerDialog.value = packager; };
const addDestination = () => { if (!destinationToAdd.value) return; const destination = createDefaultDestination(destinationToAdd.value as WorkflowDestinationV2["serviceId"], modelValue.packagers, props.capabilities); const hasCompatiblePackager = modelValue.packagers.some((packager) => packager.enabled && service(destination.serviceId).compatiblePackagers.includes(packager.definitionId)); if (!hasCompatiblePackager) { const definitionId = service(destination.serviceId).compatiblePackagers[0]; modelValue.packagers.push(createDefaultPackager(definitionId, undefined, props.capabilities)); } modelValue.destinations.push(destination); destinationToAdd.value = undefined; touch(); };
const removeDestination = (id: string) => { modelValue.destinations = modelValue.destinations.filter((destination) => destination.id !== id); touch(); };
const openDestination = (destination: WorkflowDestinationV2) => { destinationDialog.value = destination; };
const toggleDestination = (id: string) => { const next = new Set(expandedDestinationIds.value); if (next.has(id)) next.delete(id); else next.add(id); expandedDestinationIds.value = next; };
const openSlot = (destination: WorkflowDestinationV2, slot: WorkflowDeliverySlot) => { slotDialog.value = { destination, slot }; };
const destinationFields = (id: WorkflowDestinationV2["serviceId"]) => id === "steam" ? [{ key: "accountConnectionId", label: "Steam account", placeholder: "Search saved Steam connections" }, { key: "appId", label: "Steam App ID", placeholder: "123456" }, { key: "description", label: "Build description", placeholder: "Release build" }] : id === "itch" ? [{ key: "accountConnectionId", label: "Itch.io account", placeholder: "Search saved Itch.io connections" }, { key: "project", label: "Itch.io project", placeholder: "owner/project-slug", description: "Use the owner and project slug from the Itch.io project URL, for example studio-name/my-game." }] : [];
const connectionOptions = (serviceId: WorkflowDestinationV2["serviceId"]) => {
  const pluginName = serviceId === "itch" ? "@pipelab/plugin-itch" : "@pipelab/plugin-steam";
  const integrationName = serviceId === "itch" ? "Itch Butler Account" : "Steam Account";
  return (props.connections || []).filter((connection) => connection.pluginName === pluginName && connection.integrationName === integrationName);
};
const destinationSummary = (destination: WorkflowDestinationV2) => {
  if (destination.serviceId === "steam") return String(destination.config.appId || "App ID not set");
  if (destination.serviceId === "itch") return String(destination.config.project || "Project not set");
  return destination.serviceId === "zip" ? "Select an artifact and ZIP path" : "Select an artifact and output folder";
};
const setDestinationField = (destination: WorkflowDestinationV2, key: string, value: unknown) => { destination.config[key] = value; touch(); };
const compatible = (destination: WorkflowDestinationV2, packager: WorkflowPackager, output: ArtifactOutputDescriptor) => packager.enabled && service(destination.serviceId).compatiblePackagers.includes(packager.definitionId) && service(destination.serviceId).compatiblePlatforms.includes(output.platform);
const slotOptions = (destination: WorkflowDestinationV2) => modelValue.packagers.flatMap((packager) => definition(packager.definitionId).outputs.filter((output) => compatible(destination, packager, output) && (packager.config.targets === undefined || (packager.config.targets as string[]).includes(output.id))).map((output) => ({ key: `${packager.id}:${output.id}`, label: `${packager.name} · ${output.label}`, value: { packagerId: packager.id, outputId: output.id }, output })));
const slotKey = (slot: WorkflowDeliverySlot) => `${slot.input.packagerId}:${slot.input.outputId}`;
const setSlotInput = (destination: WorkflowDestinationV2, slot: WorkflowDeliverySlot, key: string) => { const option = slotOptions(destination).find((candidate) => candidate.key === key); if (option) slot.input = option.value; touch(); };
const setSlotConfig = (slot: WorkflowDeliverySlot, key: string, value: unknown) => { slot.config[key] = value; touch(); };
const setSlotEnabled = (slot: WorkflowDeliverySlot, enabled: boolean) => { slot.enabled = enabled; touch(); };
const slotLabel = (slot: WorkflowDeliverySlot) => String(slot.config.name || slot.config.channel || outputDescriptor(slot.input.outputId)?.label || slot.input.outputId);
const slotSummary = (destination: WorkflowDestinationV2, slot: WorkflowDeliverySlot) => {
  if (destination.serviceId === "steam") return `Depot ${String(slot.config.depotId || "not set")}`;
  if (destination.serviceId === "itch") return `Channel ${String(slot.config.channel || "not set")}`;
  if (destination.serviceId === "web-folder") return String(slot.config.outputDir || destination.config.outputDir || "Output folder not set");
  if (destination.serviceId === "zip") return String(slot.config.outputPath || "ZIP file not set");
  return "Select an artifact";
};
const availability = (packager: WorkflowPackager, outputId: WorkflowArtifactOutputId) => props.capabilities?.packagers[packager.definitionId]?.targets.find((target) => target.outputId === outputId) || getTargetAvailability(packager.definitionId, outputDescriptor(outputId)!, host.value);
const selectedTarget = (packager: WorkflowPackager, outputId: WorkflowArtifactOutputId) => (packager.config.targets as string[] | undefined)?.includes(outputId) ?? true;
const consumersForTarget = (packagerId: string, outputId: string) => modelValue.destinations.flatMap((destination) => destination.slots.filter((slot) => slot.input.packagerId === packagerId && slot.input.outputId === outputId).map(() => destination.id));
const targetDisabled = (packager: WorkflowPackager, outputId: WorkflowArtifactOutputId) => consumersForTarget(packager.id, outputId).length > 0;
const targetLockReason = (packager: WorkflowPackager, outputId: WorkflowArtifactOutputId) => { const users = modelValue.destinations.flatMap((destination) => destination.slots.filter((slot) => slot.input.packagerId === packager.id && slot.input.outputId === outputId).map(() => `${service(destination.serviceId).label} ${service(destination.serviceId).slotLabel}`)); return users.length ? `Can’t unselect: used by ${users.join(", ")}. Reassign or remove those slots first.` : undefined; };
const fieldValue = (packager: WorkflowPackager, field: (typeof PACKAGER_DEFINITIONS.electron.fields)[number]) => packager.config[field.key] ?? field.defaultValue;
const setField = (packager: WorkflowPackager, field: (typeof PACKAGER_DEFINITIONS.electron.fields)[number], value: unknown) => { packager.config[field.key] = field.kind === "array" ? String(value || "").split(",").map((item) => item.trim()).filter(Boolean) : value; touch(); };
const setTarget = (packager: WorkflowPackager, outputId: WorkflowArtifactOutputId, checked: boolean) => { const targets = Array.isArray(packager.config.targets) ? [...packager.config.targets as WorkflowArtifactOutputId[]] : definition(packager.definitionId).outputs.map((output) => output.id); packager.config.targets = checked ? [...new Set([...targets, outputId])] : targets.filter((id) => id !== outputId); touch(); };
const slotIsAvailable = (destination: WorkflowDestinationV2, slot: WorkflowDeliverySlot) => { const packager = modelValue.packagers.find((item) => item.id === slot.input.packagerId); const output = packager && outputDescriptor(slot.input.outputId); return !(slot.config.migration as { unresolved?: boolean } | undefined)?.unresolved && !!(packager && output && compatible(destination, packager, output) && selectedTarget(packager, output.id) && availability(packager, output.id).available); };
const addSlot = (destination: WorkflowDestinationV2) => { const option = slotOptions(destination)[0]; if (!option) return; destination.slots.push({ id: `${destination.id}-slot-${Math.random().toString(36).slice(2, 8)}`, enabled: true, config: {}, input: option.value }); touch(); };
const removeSlot = (destination: WorkflowDestinationV2, id: string) => { destination.slots = destination.slots.filter((slot) => slot.id !== id); if (slotDialog.value?.slot.id === id) slotDialog.value = undefined; touch(); };
const destinationInfoReady = (destination: WorkflowDestinationV2) => {
  const slots = destination.slots.filter((slot) => slot.enabled !== false);
  if (!slots.length) return false;
  if (destination.serviceId === "steam") return Boolean(String(destination.config.accountConnectionId || "").trim() && String(destination.config.appId || "").trim() && slots.every((slot) => String(slot.config.depotId || "").trim()));
  if (destination.serviceId === "itch") return Boolean(String(destination.config.accountConnectionId || "").trim() && String(destination.config.project || "").trim() && slots.every((slot) => String(slot.config.channel || "").trim()));
  if (destination.serviceId === "web-folder") return Boolean(slots.every((slot) => String(slot.config.outputDir || destination.config.outputDir || "").trim()));
